#!/usr/bin/env python3
from copy import deepcopy

# Helper: convert minutes (after midnight) to formatted time string (e.g., "9:00AM")
def format_time(t):
    hour = t // 60
    minute = t % 60
    suffix = "AM" if hour < 12 else "PM"
    # convert hour to 12‐hour clock:
    if hour == 0:
        hour = 12
    elif hour > 12:
        hour = hour - 12
    return f"{hour}:{minute:02d}{suffix}"

# Our travel times matrix (all times in minutes)
