# Friend appointment data.
# Times are in minutes after midnight.
friends = {
    "George": {
        "location": "Alamo Square",
        "start": 7*60+15,    # 7:15AM -> 435
        "end": 17*60+15,     # 5:15PM -> 1035
        "duration": 45
    },
    "John": {
        "location": "North Beach",
        "start": 12*60+45,   # 12:45PM -> 765
