# In our search we have 9 friends available.
# (In our best schedule the DFS chooses the order that allows maximum friend count)

# We set our start state: we start at Bayview at 9:00AM (540 minutes)
start_location = "Bayview"
start_time = 9*60  # 540 minutes

# We now do a depth–first search over all orders.
# state: current_time, current_location, visited (set of friend names), schedule (list of strings)
best_result = {"count": 0, "schedule": []}

def dfs(current_time, current_location, visited, schedule):
    global best_result
    made_progress = False
    # Try every friend not yet visited
    for friend_name, info in friends.items():
        if friend_name in visited:
            continue
        # Travel time from current location to friend location
        if current_location not in travel_times or info["location"] not in travel_times[current_location]:
            continue  # no data (should not happen)
        t_travel = travel_times[current_location][info["location"]]
        arrival_time = current_time + t_travel
        # The meeting cannot start before friend availability start.
        meeting_start = max(arrival_time, info["start"])
        meeting_end = meeting_start + info["duration"]
        # Check feasibility: meeting must finish by friend's available end.
        if meeting_end > info["end"]:
            continue
        # Prepare steps for this meeting:
        new_steps = []
        # Describe the travel step.
        step_travel = f"You travel to {info['location']} in {t_travel} minutes and arrive at {format_time(arrival_time)}."
        new_steps.append(step_travel)
        # If arrival is before the start time, we wait.
        if arrival_time < info["start"]:
            step_wait = f"You wait until {format_time(info['start'])}."
            new_steps.append(step_wait)
        # Meeting step.
        step_meet = f"You meet {friend_name} for {info['duration']} minutes from {format_time(meeting_start)} to {format_time(meeting_end)}."
        new_steps.append(step_meet)

        # Recurse with updated state.
        new_visited = visited | {friend_name}
        new_schedule = schedule + new_steps
        dfs(meeting_end, info["location"], new_visited, new_schedule)
        made_progress = True
    # If no further friend can be scheduled, update the best_result if count is higher.
    current_count = len(visited)
    if current_count > best_result["count"]:
        best_result["count"] = current_count
        best_result["schedule"] = deepcopy(schedule)

# Our initial schedule has the starting message.
initial_schedule = [f"You start at {start_location} at {format_time(start_time)}."]
dfs(start_time, start_location, set(), initial_schedule)

# For demonstration, we print the best schedule found.
print("Best schedule to maximize the number of friend meetings:")
for line in best_result["schedule"]:
    print(line)
